+fn canonical_operation_order(operations: BTreeMap<ReleaseOperationId, ReleaseOperation>) -> Result<Vec<ReleaseOperation>, GraphError> {
+    let mut remaining: BTreeMap<_, usize> = operations.iter().map(|(id, operation)| (id.clone(), operation.prerequisites().len())).collect();
