+
+fn manifest_role_text(role: &callisto_model::ManifestRole) -> String {
+    match role {
+        callisto_model::ManifestRole::Canonical => "canonical".to_string(),
+        callisto_model::ManifestRole::Lockfile => "lockfile".to_string(),
+        callisto_model::ManifestRole::Platform { platform, arch, abi } => format!("platform:{platform}:{arch}:{}", abi.as_deref().unwrap_or("")),
+    }
+}
+
+fn canonical_operation_order(operations: BTreeMap<ReleaseOperationId, ReleaseOperation>) -> Result<Vec<ReleaseOperation>, GraphError> {
+    let mut remaining: BTreeMap<_, usize> = operations.iter().map(|(id, operation)| (id.clone(), operation.prerequisites().len())).collect();
+    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
+    for (id, operation) in &operations {
+        for prerequisite in operation.prerequisites() { dependents.entry(prerequisite.clone()).or_default().push(id.clone()); }
+    }
+    let mut ready: BTreeSet<_> = remaining.iter().filter_map(|(id, count)| (*count == 0).then_some(id.clone())).collect();
+    let mut ordered = Vec::with_capacity(operations.len());
+    while let Some(id) = ready.pop_first() {
+        ordered.push(operations.get(&id).expect("known operation").clone());
+        for dependent in dependents.get(&id).into_iter().flatten() {
+            let count = remaining.get_mut(dependent).expect("known operation");
+            *count -= 1;
+            if *count == 0 { ready.insert(dependent.clone()); }
+        }
+    }
