+        PublishTarget::CratesIo => Ok("target=crates-io".to_string()),
+        PublishTarget::Npm { registry, access } => Ok(format!("target=npm:{}:{access:?}", endpoint("npm", registry.as_ref())?)),
+        PublishTarget::Pypi { index } => Ok(format!("target=pypi:{}", endpoint("pypi", index.as_ref())?)),
+        PublishTarget::NuGet { source } => Ok(format!("target=nuget:{}", endpoint("nuget", source.as_ref())?)),
+        PublishTarget::GitHubRelease => Ok("target=github-release".to_string()),
+        PublishTarget::None => Ok("target=none".to_string()),
+        #[allow(unreachable_patterns)]
+        _ => Err(GraphError::ReleaseIntentStale),
+    }
+}
+
+/// Normalizes scheme, authority (including explicit port), and path. Inputs
+/// that could contain credentials or ambiguous routing are rejected before
+/// they can affect a durable fingerprint.
+fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
+    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "missing scheme" })?;
+    if scheme.is_empty() || remainder.is_empty() { return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "empty scheme or authority" }); }
+    if remainder.contains('@') { return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "userinfo is forbidden" }); }
+    if remainder.contains('?') { return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "query string is forbidden" }); }
+    if remainder.contains('#') { return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "fragment is forbidden" }); }
+    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
+    if authority.is_empty() || authority.chars().any(char::is_whitespace) { return Err(GraphError::UnsafeRegistryBinding { registry: registry.to_string(), reason: "invalid authority" }); }
+    Ok(format!("{}://{}{}", scheme.to_ascii_lowercase(), authority.to_ascii_lowercase(), if path.is_empty() { String::new() } else { format!("/{path}") }))
